import {escapeHTML as e,plain,imageURL} from './store.js';
export function dashboard(w,o,counts,btn,settings,state){
 const all=[...w.notes,...w.folderNotes],recent=[...all].sort((a,b)=>String(b.updated).localeCompare(String(a.updated))).slice(0,4),chosen=all.find(n=>n.id===w.goalDocument)||recent[0],words=chosen?plain(chosen.body).split(/\s+/).filter(Boolean).length:0,goal=Math.max(1,Number(w.writingGoal)||1500),pct=Math.min(100,Math.round(words/goal*100));
 const docButton=(doc,cls='')=>`<button class="${cls}" data-dashboard-document="${e(doc.id)}"><span>▤</span><span><strong>${e(doc.emoji||'')} ${e(doc.title)}</strong><small>${doc.folder?'Documento de pasta':'Documento'} · ${e(w.name)}</small></span><span>↗</span></button>`;
 const title=o.title==='Seu universo começa aqui.'?`Olá, ${state.profileName||'Ana'}`:o.title,intro=o.intro==='Dê espaço às suas ideias. O extraordinário está nos detalhes.'?'O que vamos criar hoje?':o.intro;
 return `<div class="page overview-page atelier-home"><section class="atelier-welcome"><div class="page-heading"><div><span class="eyebrow">SEU ESPAÇO PARA IMAGINAR</span><h1>${e(title)}</h1><p>${e(intro)}</p></div>${settings}</div>${o.hero?`<div class="atelier-cover hero"><img src="${e(o.cover)}" alt="Capa do universo"><div class="cover-controls"><button id="changeCover">▧ Trocar capa</button><button id="resetCover" title="Restaurar capa original">↺</button></div><input type="file" id="overviewCoverFile" accept="image/*" hidden><div class="hero-content"><h2>${e(o.bannerTitle).replaceAll('\n','<br>')}</h2><p>${e(o.bannerText).replaceAll('\n','<br>')}</p></div></div>`:''}</section><div class="atelier-actions">${btn('＋ Novo documento','note')}${btn('♙ Nova ficha','character','ghost')}${btn('⌖ Novo mapa','map','ghost')}<button class="button ghost" data-dashboard-view="timeline">⌁ Linha do tempo</button>${btn('↥ Importar backup','import','ghost')}</div><section class="atelier-worlds"><div class="section-heading"><h2>✧ Seus mundos</h2><span>${state.worlds.length} ${state.worlds.length===1?'universo':'universos'}</span></div><div class="world-card-grid">${state.worlds.map((item,i)=>`<button class="atelier-world-card ${w.id===item.id?'current':''}" data-world="${e(item.id)}"><div class="world-card-cover" style="background-image:linear-gradient(90deg,#10243225,#10243210),url('${imageURL(item.overview?.cover)||['assets/castle.jpg','assets/forest.jpg','assets/journey.jpg'][i%3]}')"><span>${w.id===item.id?'Universo atual':'Abrir universo'} ↗</span></div><div><h3>${e(item.name)}</h3><p>${e(item.subtitle)} · ${(item.notes?.length||0)+(item.folderNotes?.length||0)} documentos</p></div></button>`).join('')}<button class="atelier-world-new" data-action="world"><span>＋</span>Criar novo universo</button></div></section>${o.shortcuts?`<section class="atelier-quick"><div class="section-heading"><h2>✧ Acesso rápido</h2></div><div class="atelier-quick-grid">${recent[0]?docButton(recent[0],'atelier-quick-item'):`<button class="atelier-quick-item" data-action="note">▤ Criar primeiro documento</button>`}<button class="atelier-quick-item" data-dashboard-view="characters"><span>♙</span><span><strong>Personagens</strong><small>${w.characters.length} fichas · ${e(w.name)}</small></span><span>↗</span></button><button class="atelier-quick-item" data-dashboard-view="maps"><span>⌖</span><span><strong>${e(w.maps[0]?.name||'Atlas de mapas')}</strong><small>${w.maps.length} ${w.maps.length===1?'mapa':'mapas'} no universo</small></span><span>↗</span></button><button class="atelier-quick-item" data-dashboard-view="scenes"><span>✎</span><span><strong>Continuar a escrita</strong><small>${w.narrative?.scenes?.length||0} cenas · Manuscrito</small></span><span>↗</span></button></div></section>`:''}<div class="atelier-panels">${o.recent?`<section class="atelier-panel"><div class="section-heading"><h2>◷ Últimos documentos</h2></div><div class="atelier-activity">${recent.map(n=>docButton(n)).join('')||'<p class="help">Suas próximas páginas aparecerão aqui.</p>'}</div></section>`:''}<section class="atelier-panel writing-goals"><div class="section-heading"><h2>✎ Meta de escrita</h2></div><div class="writing-goal-content"><div class="goal-ring" style="--progress:${pct}%"><strong id="goalPercent">${pct}%</strong></div><div><label class="field"><span>Documento</span><select id="goalDocument">${all.length?all.map(n=>`<option value="${e(n.id)}" ${chosen?.id===n.id?'selected':''}>${e(n.title)}</option>`).join(''):'<option>Nenhum documento</option>'}</select></label><p><strong id="goalWords">${words}</strong> palavras escritas</p><label class="goal-input">Objetivo <input id="writingGoal" type="number" min="1" max="1000000" value="${goal}" aria-label="Meta de palavras"></label><progress id="goalProgress" value="${words}" max="${goal}"></progress></div></div></section>${o.inspiration?`<section class="atelier-panel atelier-ideas"><div class="section-heading"><h2>♧ Ideias e inspirações</h2></div><div id="ideaScratch" contenteditable="plaintext-only" role="textbox" aria-label="Ideias e inspirações" data-placeholder="Capture uma ideia para depois…">${e(o.scratch||'')}</div><blockquote><span data-overview-field="quote">${e(o.quote)}</span><small data-overview-field="author">${e(o.author)}</small></blockquote></section>`:''}</div>${o.stats?`<div class="atelier-counters">${[['notes','Documentos',all.length],['characters','Personagens',w.characters.length],['maps','Mapas',w.maps.length],['bestiary','Criaturas',w.bestiary.length]].map(([key,label,count])=>`<button data-dashboard-view="${key}"><strong>${count}</strong> ${label}</button>`).join('')}</div>`:''}${o.map?`<section class="atelier-map-strip"><button data-dashboard-view="maps"><img src="${imageURL(w.maps[0]?.image)||'assets/eldoria.svg'}" alt="Mapa do universo"><span><strong>Explore seu mundo</strong><small>${w.maps.reduce((sum,m)=>sum+m.pins.length,0)} regiões no atlas · Abrir mapa ↗</small></span></button></section>`:''}</div>`;
}
export function mountDashboard(main,w,{save,rerender,openDocument,navigate}){
 const abort=new AbortController(),opts={signal:abort.signal};main.querySelectorAll('[data-dashboard-document]').forEach(b=>b.addEventListener('click',()=>openDocument(b.dataset.dashboardDocument),opts));main.querySelectorAll('[data-dashboard-view]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.dashboardView),opts));const scratch=main.querySelector('#ideaScratch');scratch?.addEventListener('input',()=>{w.overview.scratch=scratch.innerText.slice(0,10000);save();},opts);main.querySelector('#goalDocument')?.addEventListener('change',ev=>{w.goalDocument=ev.target.value;save();rerender();},opts);main.querySelector('#writingGoal')?.addEventListener('input',ev=>{const value=Number(ev.target.value);if(!Number.isInteger(value)||value<1||value>1000000)return;w.writingGoal=value;save();const words=Number(main.querySelector('#goalWords').textContent),pct=Math.min(100,Math.round(words/value*100));main.querySelector('#goalPercent').textContent=pct+'%';main.querySelector('.goal-ring').style.setProperty('--progress',pct+'%');main.querySelector('#goalProgress').max=value;},opts);return ()=>abort.abort();
}
